// A `use` path names a module with a token rather than an expression, and the
// qualified call below names the same module as one.
// The import that bound it and both are places this module is used.
import sizes

use sizes.Width

fn main() -> UInt8 {
    let w: Width = .{ of = 2 }
    sizes.twice(w.of)
}

pub struct Width {
    of: UInt8,
}

pub fn twice(n: UInt8) -> UInt8 {
    n * 2
}
